@@ -2006,14 +2006,17 @@ void delwatch(des_proc *p)
 bool handle_watch_pf(vaddr cr2)
 {
 	watch_des *w = &watch_state;
+	flog(LOG_DEBUG, "handle_watch_pf: cr2=%lx w->v=%lx", cr2, w->v);

 	if (!w->v) {
 		// non ci sono watch attivi
+		flog(LOG_DEBUG, "handle_watch_pf: no watch active");
 		return false;
 	}

 	if (base(cr2, 0) != base(w->v, 0)) {
 		// l'accesso non riguarda il watch corrente
+		flog(LOG_DEBUG, "handle_watch_pf: wrong page");
 		return false;
 	}

@@ -2044,9 +2047,56 @@ bool handle_watch_pf(vaddr cr2)
  */
 bool handle_watch_ss()
 {
-/// @todo Gestire l'evento
-// ( SOLUZIONE 2024-06-07
-//   SOLUZIONE 2024-06-07 )
+	watch_des *w = &watch_state;
+
+	if (!w->v || !esecuzione->being_watched) {
+		// non c'è un watch attivo o il processo non è watched
+		return false;
+	}
+
+	// disabilitiamo il Single Step
+	natq *pila = ptr_cast<natq>(esecuzione->contesto[I_RSP]);
+	pila[2] &= ~BIT_TF;
+
+	// leggiamo il nuovo valore della variabile osservata
+	natq new_value = 0;
+	memcpy(&new_value, voidptr_cast(w->v), w->size);
+
+	// salviamo il processo watched prima di eventuale schedulazione
+	des_proc *watched = esecuzione;
+
+	// disabilitiamo being_watched
+	watched->being_watched = false;
+
+	// riabilitiamo le scritture sulla pagina
+	tab_iter it(watched->cr3, w->v, w->size);
+	while (it.down())
+		;
+	it.get_e() &= ~BIT_RW;
+	// invalidiamo la TLB per assicurarci che la modifica sia visibile
+	asm volatile("invlpg (%0)" :: "r"(w->v) : "memory");
+
+	// se il valore è cambiato, passiamolo al watcher
+	if (new_value != w->old_value) {
+		w->old_value = new_value;
+		watched->new_watch_value = new_value;
+
+		// se il watcher è in attesa, lo risvegliamo
+		if (w->watcher_waiting) {
+			des_proc *watcher = rimozione_lista(w->watcher_waiting);
+			watcher->contesto[I_RAX] = watched->new_watch_value;
+			watched->new_watch_value = 0;
+			inserimento_lista(pronti, watched);
+			inserimento_lista(pronti, watcher);
+			schedulatore();
+		} else {
+			// altrimenti il watched si mette in attesa
+			inserimento_in_fondo(w->watched_waiting, watched);
+			schedulatore();
+		}
+	}
+
+	return true;
 }

 /**
@@ -2054,9 +2104,34 @@ bool handle_watch_ss()
  */
 extern "C" void c_watch()
 {
-/// @todo Realizzare la primitiva
-// ( SOLUZIONE 2024-06-07
-//   SOLUZIONE 2024-06-07 )
+	watch_des *w = &watch_state;
+
+	if (!w->v) {
+		// non ci sono watch installati
+		flog(LOG_WARN, "watch: nessun watch installato");
+		c_abort_p();
+		return;
+	}
+
+	if (esecuzione->id != w->watcher_id) {
+		// il processo non è il watcher corrente
+		flog(LOG_WARN, "watch: processo %u non è il watcher %u", esecuzione->id, (natl)w->watcher_id);
+		c_abort_p();
+		return;
+	}
+
+	// se c'è un processo watched in attesa, lo risvegliamo e restituiamo il suo valore
+	if (w->watched_waiting) {
+		des_proc *watched = rimozione_lista(w->watched_waiting);
+		esecuzione->contesto[I_RAX] = watched->new_watch_value;
+		watched->new_watch_value = 0;
+		inserimento_lista(pronti, watched);
+		schedulatore();
+	} else {
+		// nessun processo watched in attesa: sospendiamo il watcher
+		inserimento_in_fondo(w->watcher_waiting, esecuzione);
+		schedulatore();
+	}
 }
 //   ESAME 2024-06-07 )
 /// @}
